# owner: platform
"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError

def contact_rows(students):
    """Text rows of name, section and email, by name."""
    if not students:
        raise ProjectError("no students for contact sheet")
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    width = max(len(item.display_name) for item in ordered)
    sect = max(len(item.section) for item in ordered)
    return [
        f"{item.display_name:<{width}}  "
        f"{item.section:<{sect}}  {item.email}"
        for item in ordered
    ]

